/*********************************************************************
 * Seed / bulk load (SnowSQL) — loads data/seed/*.csv into BANKING_DW.
 * Production equivalent of the Teradata FastLoad/TPT step: PUT to an
 * internal stage, then COPY INTO with a pipe-delimited file format.
 *
 * Run from the repo root:
 *   snowsql -c etl_svc -f snowflake/dml/scripts/load_seed_data.sql
 *
 * Surrogate keys (CUSTOMER_KEY, ACCOUNT_KEY) are generated by AUTOINCREMENT
 * because the seed files carry no keys. For a full historical migration,
 * load the Teradata-assigned keys explicitly (fact tables reference them)
 * and make sure the identity's next value is above the highest loaded key
 * (e.g. create the table with START <max key + 1>); see MIGRATION_RUNBOOK.md,
 * "Surrogate keys".
 *********************************************************************/

USE SCHEMA BANKING_DW;

CREATE OR REPLACE FILE FORMAT BANKING_DW.FF_PIPE_CSV
    TYPE = CSV
    FIELD_DELIMITER = '|'
    SKIP_HEADER = 1
    EMPTY_FIELD_AS_NULL = TRUE
    NULL_IF = ('')
    DATE_FORMAT = 'YYYY-MM-DD';

CREATE OR REPLACE STAGE BANKING_DW.STG_SEED FILE_FORMAT = BANKING_DW.FF_PIPE_CSV;

PUT file://data/seed/*.csv @BANKING_DW.STG_SEED AUTO_COMPRESS = TRUE OVERWRITE = TRUE;

COPY INTO BANKING_DW.DIM_CUSTOMER (
    CUSTOMER_ID, FIRST_NAME, LAST_NAME, DATE_OF_BIRTH, GENDER, MARITAL_STATUS,
    EMAIL_ADDRESS, PHONE_NUMBER, ADDRESS_LINE_1, ADDRESS_LINE_2, CITY,
    STATE_PROVINCE, POSTAL_CODE, COUNTRY_CODE, CUSTOMER_SEGMENT, RISK_SCORE,
    CREDIT_RATING, KYC_STATUS, ONBOARDING_DATE, IS_ACTIVE)
FROM @BANKING_DW.STG_SEED/dim_customer_sample.csv.gz
ON_ERROR = ABORT_STATEMENT;

COPY INTO BANKING_DW.DIM_ACCOUNT (
    ACCOUNT_ID, CUSTOMER_ID, ACCOUNT_TYPE, ACCOUNT_SUBTYPE, CURRENCY_CODE,
    OPENING_DATE, ACCOUNT_STATUS, INTEREST_RATE, CREDIT_LIMIT, OVERDRAFT_LIMIT,
    BRANCH_ID, PRODUCT_ID, IS_JOINT_ACCOUNT)
FROM @BANKING_DW.STG_SEED/dim_account_sample.csv.gz
ON_ERROR = ABORT_STATEMENT;

COPY INTO BANKING_DW.DIM_PRODUCT (
    PRODUCT_ID, PRODUCT_CODE, PRODUCT_NAME, PRODUCT_CATEGORY, PRODUCT_SUBCATEGORY,
    BASE_INTEREST_RATE, MIN_BALANCE, FEE_STRUCTURE, MONTHLY_FEE, IS_REGULATED,
    LAUNCH_DATE, IS_ACTIVE)
FROM @BANKING_DW.STG_SEED/dim_product_sample.csv.gz
ON_ERROR = ABORT_STATEMENT;

COPY INTO BANKING_DW.DIM_BRANCH (
    BRANCH_ID, BRANCH_CODE, BRANCH_NAME, BRANCH_TYPE, CITY, COUNTY, REGION,
    POSTAL_CODE, COUNTRY_CODE, LATITUDE, LONGITUDE, OPENING_DATE, IS_ACTIVE,
    EMPLOYEE_COUNT)
FROM @BANKING_DW.STG_SEED/dim_branch_sample.csv.gz
ON_ERROR = ABORT_STATEMENT;
